CREATE POLICY "Parish media readable" ON storage.objects FOR SELECT TO anon, authenticated USING (bucket_id = 'parish-media');
CREATE POLICY "Admins upload parish media" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'parish-media' AND public.has_role(auth.uid(), 'admin'));
CREATE POLICY "Admins update parish media" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'parish-media' AND public.has_role(auth.uid(), 'admin')) WITH CHECK (bucket_id = 'parish-media' AND public.has_role(auth.uid(), 'admin'));
CREATE POLICY "Admins delete parish media" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'parish-media' AND public.has_role(auth.uid(), 'admin'));